-- ---------------------------------------------------------------------------
-- Rules Prisma cannot express (hand-written, 2026-10-26)
-- ---------------------------------------------------------------------------

-- Trainer list rows
ALTER TABLE "TrainerProfile" ADD CONSTRAINT "TrainerProfile_fellow_chk"
  CHECK ("fellowshipYear" IS NULL OR "fellowshipYear" BETWEEN 1960 AND 2100);
-- Moved means moved to a different hospital; nothing else carries a destination.
ALTER TABLE "TrainerProfile" ADD CONSTRAINT "TrainerProfile_status_chk"
  CHECK (("listStatus"::text = 'MOVED' AND "movedToHospitalId" IS NOT NULL AND "hospitalId" IS NOT NULL AND "movedToHospitalId" <> "hospitalId")
      OR ("listStatus"::text <> 'MOVED' AND "movedToHospitalId" IS NULL));
-- Only an unplaced import (on the list, or kept aside as retired) may have no hospital.
ALTER TABLE "TrainerProfile" ADD CONSTRAINT "TrainerProfile_hosp_chk"
  CHECK ("hospitalId" IS NOT NULL OR "listStatus"::text IN ('ON_LIST', 'RETIRED'));
ALTER TABLE "TrainerProfile" ADD CONSTRAINT "TrainerProfile_dates_chk"
  CHECK ("leftOn" IS NULL OR "joinedOn" IS NULL OR "leftOn" >= "joinedOn");

-- A trainer can only also be a trainee for ICU or pain training. A current anaesthesia trainee
-- (BAT, HAT or PFY) cannot be on a trainer list; a Fellow who has completed training can.
CREATE FUNCTION "trainer_not_current_trainee"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW."listStatus"::text = 'ON_LIST' AND EXISTS (
       SELECT 1 FROM "TraineeProfile" t
        WHERE t."userId" = NEW."userId" AND t."programme"::text = 'ANAESTHESIA' AND t."currentStage"::text <> 'FELLOW') THEN
    RAISE EXCEPTION 'trainer_is_trainee: a current anaesthesia trainee cannot be on a trainer list';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER "TrainerProfile_not_trainee" BEFORE INSERT OR UPDATE OF "listStatus", "userId" ON "TrainerProfile"
  FOR EACH ROW EXECUTE FUNCTION "trainer_not_current_trainee"();

CREATE FUNCTION "trainee_not_current_trainer"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW."programme"::text = 'ANAESTHESIA' AND NEW."currentStage"::text <> 'FELLOW' AND EXISTS (
       SELECT 1 FROM "TrainerProfile" p WHERE p."userId" = NEW."userId" AND p."listStatus"::text = 'ON_LIST') THEN
    RAISE EXCEPTION 'trainee_is_trainer: someone on a trainer list cannot become an anaesthesia trainee';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER "TraineeProfile_not_trainer" BEFORE INSERT OR UPDATE OF "programme", "currentStage", "userId" ON "TraineeProfile"
  FOR EACH ROW EXECUTE FUNCTION "trainee_not_current_trainer"();

-- An SOT or Assistant SOT in post is a trainer of that hospital, on the same login.
-- Appointing one puts (or keeps) them on the hospital's list; a future start date is applied by the daily job.
CREATE FUNCTION "sot_is_trainer"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW."role"::text IN ('SOT', 'ASSISTANT_SOT') AND NEW."isActive" AND NEW."scopeType" = 'HOSPITAL' AND NEW."scopeId" IS NOT NULL
     AND NEW."effectiveFrom" <= now() AND (NEW."effectiveUntil" IS NULL OR NEW."effectiveUntil" > now()) THEN
    INSERT INTO "TrainerProfile" (id, "userId", "hospitalId", "isSot", "isAssistantSot", qualifications, "listStatus")
    VALUES (gen_random_uuid()::text, NEW."userId", NEW."scopeId", NEW."role"::text = 'SOT', NEW."role"::text = 'ASSISTANT_SOT', ARRAY[]::text[], 'ON_LIST')
    ON CONFLICT ("userId") DO UPDATE SET
      "hospitalId" = EXCLUDED."hospitalId", "listStatus" = 'ON_LIST', "movedToHospitalId" = NULL, "leftOn" = NULL,
      "isSot" = "TrainerProfile"."isSot" OR EXCLUDED."isSot",
      "isAssistantSot" = "TrainerProfile"."isAssistantSot" OR EXCLUDED."isAssistantSot";
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER "UserRoleAssignment_sot_is_trainer" AFTER INSERT OR UPDATE ON "UserRoleAssignment"
  FOR EACH ROW EXECUTE FUNCTION "sot_is_trainer"();

-- ...and cannot be marked as left, moved or retired while in post: end the appointment first.
CREATE FUNCTION "sot_must_stay_trainer"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW."listStatus"::text <> 'ON_LIST' AND EXISTS (
       SELECT 1 FROM "UserRoleAssignment" r
        WHERE r."userId" = NEW."userId" AND r."role"::text IN ('SOT', 'ASSISTANT_SOT') AND r."isActive"
          AND r."effectiveFrom" <= now() AND (r."effectiveUntil" IS NULL OR r."effectiveUntil" > now())) THEN
    RAISE EXCEPTION 'sot_must_train: an SOT or Assistant SOT in post stays on the trainer list; end the appointment first';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER "TrainerProfile_sot_stays" BEFORE UPDATE OF "listStatus" ON "TrainerProfile"
  FOR EACH ROW EXECUTE FUNCTION "sot_must_stay_trainer"();

-- Account invitations
ALTER TABLE "AccountInvitation" ADD CONSTRAINT "AccountInvitation_expiry_chk" CHECK ("expiresAt" > "createdAt");
ALTER TABLE "AccountInvitation" ADD CONSTRAINT "AccountInvitation_closed_chk" CHECK ("usedAt" IS NULL OR "revokedAt" IS NULL);
-- One open link per person: sending a new one revokes the old one first.
CREATE UNIQUE INDEX "AccountInvitation_open_uq" ON "AccountInvitation" ("userId") WHERE "usedAt" IS NULL AND "revokedAt" IS NULL;

-- Not sent to anyone who already has a login (active account, or a trainee record): they sign in and the role is added.
CREATE FUNCTION "invitation_only_without_login"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM "User" u WHERE u.id = NEW."userId" AND u."accountStatus"::text = 'ACTIVE')
     OR EXISTS (SELECT 1 FROM "TraineeProfile" t WHERE t."userId" = NEW."userId") THEN
    RAISE EXCEPTION 'already_has_login: this person already has a login; they sign in and the role is added';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER "AccountInvitation_no_login" BEFORE INSERT ON "AccountInvitation"
  FOR EACH ROW EXECUTE FUNCTION "invitation_only_without_login"();

-- Sending a link moves the account from NONE to INVITED; using it makes the account ACTIVE. A revoked or expired link cannot be used.
CREATE FUNCTION "invitation_sent"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  UPDATE "User" SET "accountStatus" = 'INVITED' WHERE id = NEW."userId" AND "accountStatus"::text = 'NONE';
  RETURN NEW;
END $$;
CREATE TRIGGER "AccountInvitation_sent" AFTER INSERT ON "AccountInvitation"
  FOR EACH ROW EXECUTE FUNCTION "invitation_sent"();

CREATE FUNCTION "invitation_used"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW."usedAt" IS NOT NULL AND OLD."usedAt" IS NULL THEN
    IF OLD."revokedAt" IS NOT NULL OR NEW."usedAt" > OLD."expiresAt" THEN
      RAISE EXCEPTION 'invitation_not_usable: this link was revoked or has expired';
    END IF;
    UPDATE "User" SET "accountStatus" = 'ACTIVE', "accountActivatedAt" = NEW."usedAt" WHERE id = NEW."userId";
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER "AccountInvitation_used" BEFORE UPDATE OF "usedAt" ON "AccountInvitation"
  FOR EACH ROW EXECUTE FUNCTION "invitation_used"();
